with RecentCustomers as (select * from customers where age >= 47 and lower(name) like '%liv%' and is_active), SignupMonthSummary as (select date_trunc('MONTH', signup_date) signup_month, country, sum(case when city = 'New York' then 1 else 0 end) new_york_count from RecentCustomers group by date_trunc('MONTH', signup_date), country) select * from SignupMonthSummary where new_york_count > 53 order by new_york_count
